CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE SCHEMA IF NOT EXISTS core;
CREATE SCHEMA IF NOT EXISTS event;
CREATE SCHEMA IF NOT EXISTS media;
CREATE SCHEMA IF NOT EXISTS ingestion;
CREATE SCHEMA IF NOT EXISTS admin;
CREATE SCHEMA IF NOT EXISTS system;
CREATE SCHEMA IF NOT EXISTS serving;
CREATE SCHEMA IF NOT EXISTS consumer;
CREATE SCHEMA IF NOT EXISTS notification;

CREATE TABLE core.entity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_type text NOT NULL, canonical_name text NOT NULL, original_locale text, summary text, status text NOT NULL DEFAULT 'ACTIVE', metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX entity_name_trgm ON core.entity USING gin (canonical_name gin_trgm_ops);
CREATE TABLE core.entity_text (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid NOT NULL REFERENCES core.entity(id), locale text NOT NULL, field_type text NOT NULL, value text NOT NULL, provider text, provider_ref_id uuid, confidence numeric, is_primary boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE core.external_reference (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_id uuid NOT NULL REFERENCES core.entity(id), provider text NOT NULL, external_type text NOT NULL, external_id text NOT NULL, url text, source_hash text, match_method text, confidence numeric, verified boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, last_seen_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider, external_type, external_id));
CREATE TABLE core.entity_relation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), from_entity_id uuid NOT NULL REFERENCES core.entity(id), to_entity_id uuid NOT NULL REFERENCES core.entity(id), relation_type text NOT NULL, provider text, source_ref_id uuid, confidence numeric, verified boolean NOT NULL DEFAULT false, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE event.venue (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, address_line1 text, address_line2 text, city text, region text, country_code text, postal_code text, latitude double precision, longitude double precision, timezone text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE event.event (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parent_event_id uuid REFERENCES event.event(id), event_type text NOT NULL, canonical_name text NOT NULL, start_at timestamptz, end_at timestamptz, timezone text, venue_id uuid REFERENCES event.venue(id), organizer_entity_id uuid REFERENCES core.entity(id), official_url text, status text NOT NULL DEFAULT 'ACTIVE', importance_score numeric, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX event_status_start ON event.event(status, start_at);
CREATE INDEX event_name_trgm ON event.event USING gin (canonical_name gin_trgm_ops);
CREATE TABLE event.event_text (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES event.event(id), locale text NOT NULL, field_type text NOT NULL, value text NOT NULL, provider text, confidence numeric, is_primary boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE ingestion.source (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, source_type text NOT NULL, connector_key text NOT NULL, owner_entity_id uuid REFERENCES core.entity(id), base_url text, trust_level text NOT NULL, priority text NOT NULL DEFAULT 'NORMAL', enabled boolean NOT NULL DEFAULT true, poll_interval_seconds integer, config jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ingestion.source_sync_state (source_id uuid PRIMARY KEY REFERENCES ingestion.source(id), cursor text, last_version text, last_fetch_at timestamptz, last_success_at timestamptz, next_fetch_at timestamptz, last_content_hash text, status text NOT NULL DEFAULT 'IDLE', last_error text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ingestion.raw_document (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES ingestion.source(id), external_document_id text, document_type text NOT NULL, canonical_url text, title text, text_preview text, published_at timestamptz, fetched_at timestamptz NOT NULL, content_hash text NOT NULL, mime_type text, r2_key text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', processing_status text NOT NULL DEFAULT 'UNPROCESSED', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id, external_document_id));
CREATE TABLE ingestion.ingestion_run (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid REFERENCES ingestion.source(id), run_type text NOT NULL, status text NOT NULL, started_at timestamptz NOT NULL, finished_at timestamptz, records_seen integer NOT NULL DEFAULT 0, records_created integer NOT NULL DEFAULT 0, records_updated integer NOT NULL DEFAULT 0, records_skipped integer NOT NULL DEFAULT 0, records_failed integer NOT NULL DEFAULT 0, metadata jsonb NOT NULL DEFAULT '{}', error text);
CREATE TABLE ingestion.job (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_type text NOT NULL, required_capability text NOT NULL, status text NOT NULL, priority text NOT NULL, dedupe_key text NOT NULL UNIQUE, raw_document_id uuid REFERENCES ingestion.raw_document(id), payload jsonb NOT NULL DEFAULT '{}', attempt_count integer NOT NULL DEFAULT 0, max_attempts integer NOT NULL DEFAULT 3, available_at timestamptz NOT NULL, expires_at timestamptz, leased_by uuid, lease_expires_at timestamptz, superseded_by uuid REFERENCES ingestion.job(id), created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, completed_at timestamptz, last_error text);
CREATE INDEX job_lease_queue ON ingestion.job(status, priority, available_at);
CREATE TABLE ingestion.worker (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), worker_name text NOT NULL, worker_type text NOT NULL, capabilities jsonb NOT NULL, model_provider text, model_name text, status text NOT NULL, last_heartbeat_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE ingestion.job ADD CONSTRAINT job_worker_fk FOREIGN KEY (leased_by) REFERENCES ingestion.worker(id);
CREATE TABLE ingestion.candidate (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_type text NOT NULL, raw_document_id uuid REFERENCES ingestion.raw_document(id), job_id uuid REFERENCES ingestion.job(id), payload jsonb NOT NULL, confidence numeric, status text NOT NULL, reviewed_by uuid, reviewed_at timestamptz, published_entity_id uuid REFERENCES core.entity(id), published_event_id uuid REFERENCES event.event(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ingestion.assertion (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_type text NOT NULL, subject_id uuid NOT NULL, field_path text NOT NULL, value_json jsonb NOT NULL, source_id uuid NOT NULL REFERENCES ingestion.source(id), raw_document_id uuid REFERENCES ingestion.raw_document(id), confidence numeric, observed_at timestamptz NOT NULL, valid_from timestamptz, valid_to timestamptz, status text NOT NULL, content_hash text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ingestion.resolution_conflict (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_type text NOT NULL, subject_id uuid NOT NULL, field_path text NOT NULL, current_value jsonb, proposed_value jsonb, current_source text, proposed_source_id uuid REFERENCES ingestion.source(id), severity text NOT NULL, status text NOT NULL, resolution jsonb, resolved_by uuid, created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);

CREATE TABLE admin.principal (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), auth_issuer text NOT NULL, auth_subject text NOT NULL, email text, role text NOT NULL, status text NOT NULL, last_seen_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(auth_issuer, auth_subject));
ALTER TABLE ingestion.candidate ADD CONSTRAINT candidate_reviewer_fk FOREIGN KEY (reviewed_by) REFERENCES admin.principal(id);
ALTER TABLE ingestion.resolution_conflict ADD CONSTRAINT conflict_resolver_fk FOREIGN KEY (resolved_by) REFERENCES admin.principal(id);
CREATE TABLE admin.audit_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), principal_id uuid REFERENCES admin.principal(id), operation text NOT NULL, target_type text NOT NULL, target_id uuid NOT NULL, before jsonb, after jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admin.manual_override (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subject_type text NOT NULL, subject_id uuid NOT NULL, field_path text NOT NULL, value_json jsonb NOT NULL, mode text NOT NULL CHECK(mode IN ('PINNED','PREFERRED')), principal_id uuid NOT NULL REFERENCES admin.principal(id), reason text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE event.event_entity (event_id uuid NOT NULL REFERENCES event.event(id), entity_id uuid NOT NULL REFERENCES core.entity(id), relation_type text NOT NULL, origin text NOT NULL, source_id uuid REFERENCES ingestion.source(id), confidence numeric, pinned boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(event_id, entity_id, relation_type));
CREATE TABLE event.event_evidence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES event.event(id), raw_document_id uuid NOT NULL REFERENCES ingestion.raw_document(id), evidence_type text NOT NULL, confidence numeric, is_primary boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE event.event_link (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES event.event(id), link_type text NOT NULL, provider text, url text NOT NULL, affiliate_metadata jsonb NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE media.asset (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid REFERENCES ingestion.source(id), raw_document_id uuid REFERENCES ingestion.raw_document(id), origin text NOT NULL, source_url text, r2_key text, original_filename text, mime_type text, byte_size bigint, width integer, height integer, sha256 text UNIQUE, perceptual_hash text, detected_category text, classification_confidence numeric, usage_scope text NOT NULL DEFAULT 'INTERNAL_ONLY', rights_status text NOT NULL DEFAULT 'UNKNOWN', retention_policy text NOT NULL DEFAULT 'KEEP', attribution text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE media.assignment (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES media.asset(id), entity_id uuid REFERENCES core.entity(id), event_id uuid REFERENCES event.event(id), venue_id uuid REFERENCES event.venue(id), role text NOT NULL, is_default_internal boolean NOT NULL DEFAULT false, is_primary_public boolean NOT NULL DEFAULT false, pinned boolean NOT NULL DEFAULT false, priority_score numeric, sort_order integer, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(num_nonnulls(entity_id,event_id,venue_id)=1));

CREATE TABLE system.outbox_event (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL, aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL, payload jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'PENDING', available_at timestamptz NOT NULL DEFAULT now(), attempt_count integer NOT NULL DEFAULT 0, last_error text, created_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz);
CREATE TABLE serving.event_listing (event_id uuid PRIMARY KEY, slug text NOT NULL UNIQUE, status text NOT NULL, event_type text NOT NULL, title text NOT NULL, start_at timestamptz, end_at timestamptz, timezone text, city text, region text, country text, latitude double precision, longitude double precision, primary_image_url text, primary_fandom_ids uuid[], popularity_score double precision, canonical_version bigint NOT NULL, projection_version bigint NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE serving.event_document (event_id uuid PRIMARY KEY, slug text NOT NULL UNIQUE, document jsonb NOT NULL, canonical_version bigint NOT NULL, projection_version bigint NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE serving.entity_document (entity_id uuid PRIMARY KEY, slug text NOT NULL UNIQUE, entity_type text NOT NULL, display_name text NOT NULL, search_text text NOT NULL, document jsonb NOT NULL, canonical_version bigint NOT NULL, projection_version bigint NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE consumer.identity (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), auth_issuer text NOT NULL, auth_subject text NOT NULL, email text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(auth_issuer,auth_subject));
CREATE TABLE consumer.profile (identity_id uuid PRIMARY KEY REFERENCES consumer.identity(id), locale text NOT NULL DEFAULT 'en-US', latitude double precision, longitude double precision, city text, region text, country_code text, travel_tolerance_km integer NOT NULL DEFAULT 80, timezone text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE consumer.entity_follow (identity_id uuid NOT NULL REFERENCES consumer.identity(id), entity_id uuid NOT NULL REFERENCES core.entity(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(identity_id,entity_id));
CREATE TABLE consumer.event_action (identity_id uuid NOT NULL REFERENCES consumer.identity(id), event_id uuid NOT NULL, action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(identity_id,event_id,action));
CREATE TABLE consumer.device (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), identity_id uuid NOT NULL REFERENCES consumer.identity(id), platform text NOT NULL, push_token text NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification.preference (identity_id uuid PRIMARY KEY REFERENCES consumer.identity(id), event_matches boolean NOT NULL DEFAULT true, event_updates boolean NOT NULL DEFAULT true, event_reminders boolean NOT NULL DEFAULT true, email_enabled boolean NOT NULL DEFAULT false, push_enabled boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification.outbox (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), identity_id uuid NOT NULL REFERENCES consumer.identity(id), notification_type text NOT NULL, channel text NOT NULL, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'PENDING', available_at timestamptz NOT NULL DEFAULT now(), attempt_count integer NOT NULL DEFAULT 0, sent_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now());
